1	import { useState, useEffect } from "react";
2	import { useParams, useNavigate, Link } from "react-router-dom";
3	import { useQuery } from "@tanstack/react-query";
4	import { supabase } from "@/integrations/supabase/client";
5	import { Skeleton } from "@/components/ui/skeleton";
6	import { Badge } from "@/components/ui/badge";
7	import { Briefcase, Layers } from "lucide-react";
8	import JobListingCard from "@/components/career/JobListingCard";
9	
10	interface CareerConfig {
11	  company_name: string;
12	  logo_url: string | null;
13	  brand_color: string;
14	  tagline: string | null;
15	  about: string | null;
16	}
17	
18	interface CareerJob {
19	  id: string;
20	  title: string;
21	  location: string | null;
22	  department: string | null;
23	  employment_type: string | null;
24	  salary_range: string | null;
25	  created_at: string;
26	}
27	
28	export default function CareerPage() {
29	  const { slug } = useParams<{ slug: string }>();
30	  const navigate = useNavigate();
31	  const [selectedDept, setSelectedDept] = useState<string | null>(null);
32	
33	  const { data, isLoading } = useQuery({
34	    queryKey: ["career-page", slug],
35	    queryFn: async () => {
36	      if (!slug) return null;
37	      const { data, error } = await supabase.rpc("get_career_page", {
38	        p_slug: slug,
39	      });
40	      if (error) throw error;
41	      return data as { config: CareerConfig; jobs: CareerJob[] } | null;
42	    },
43	    enabled: !!slug,
44	    staleTime: 60_000,
45	  });
46	
47	  const config = data?.config;
48	  const jobs = data?.jobs ?? [];
49	  const brandColor = config?.brand_color ?? "#6366f1";
50	
51	  const departments = [
52	    ...new Set(jobs.map((j) => j.department).filter(Boolean)),
53	  ] as string[];
54	  const filteredJobs = selectedDept
55	    ? jobs.filter((j) => j.department === selectedDept)
56	    : jobs;
57	
58	  useEffect(() => {
59	    if (config) {
60	      document.title = `Careers at ${config.company_name} | Rankora`;
61	    }
62	    return () => {
63	      document.title = "Rankora";
64	    };
65	  }, [config]);
66	
67	  const handleApply = (jobId: string) => navigate(`/apply/${jobId}`);
68	
69	  // Loading
70	  if (isLoading) {
71	    return (
72	      <div className="min-h-screen bg-background flex flex-col">
73	        <header className="border-b border-border">
74	          <div className="max-w-4xl mx-auto px-4 py-4 flex items-center gap-3">
75	            <Skeleton className="h-8 w-8 rounded" />
76	            <Skeleton className="h-5 w-32" />
77	          </div>
78	        </header>
79	        <div className="max-w-4xl mx-auto px-4 py-12 w-full space-y-4">
80	          <Skeleton className="h-8 w-64 mx-auto" />
81	          <Skeleton className="h-4 w-48 mx-auto" />
82	          <div className="space-y-4 mt-8">
83	            {[1, 2, 3].map((i) => (
84	              <Skeleton key={i} className="h-24 w-full rounded-xl" />
85	            ))}
86	          </div>
87	        </div>
88	      </div>
89	    );
90	  }
91	
92	  // Not found
93	  if (!config) {
94	    return (
95	      <div className="min-h-screen bg-background flex flex-col">
96	        <header className="border-b border-border">
97	          <div className="max-w-4xl mx-auto px-4 py-4">
98	            <Link
99	              to="/"
100	              className="flex items-center gap-2 text-sm font-semibold"
101	            >
102	              <Layers className="h-5 w-5 text-primary" /> Rankora
103	            </Link>
104	          </div>
105	        </header>
106	        <main className="flex-1 flex items-center justify-center px-4 py-16">
107	          <div className="text-center space-y-4">
108	            <div className="w-14 h-14 rounded-full bg-muted flex items-center justify-center mx-auto">
109	              <Briefcase className="h-7 w-7 text-muted-foreground" />
110	            </div>
111	            <h1 className="text-xl font-semibold">Career page not found</h1>
112	            <p className="text-sm text-muted-foreground">
113	              This career page may have been removed or is not yet active.
114	            </p>
115	            <Link
116	              to="/"
117	              className="text-sm font-medium text-primary hover:text-primary/80 transition-colors"
118	            >
119	              Back to Rankora
120	            </Link>
121	          </div>
122	        </main>
123	      </div>
124	    );
125	  }
126	
127	  // Active career page
128	  return (
129	    <div className="min-h-screen bg-background flex flex-col">
130	      {/* Header */}
131	      <header className="sticky top-0 z-10 bg-background/95 backdrop-blur border-b border-border">
132	        <div className="max-w-4xl mx-auto px-4 py-4 flex items-center gap-3">
133	          {config.logo_url && (
134	            <img
135	              src={config.logo_url}
136	              alt={config.company_name}
137	              className="h-8 w-8 rounded object-cover"
138	            />
139	          )}
140	          <span className="font-semibold text-lg text-foreground">
141	            {config.company_name}
142	          </span>
143	        </div>
144	      </header>
145	
146	      {/* Hero */}
147	      <div className="py-12 px-4" style={{ backgroundColor: brandColor + "0D" }}>
148	        <div className="max-w-4xl mx-auto text-center space-y-3">
149	          <h1 className="text-3xl font-bold text-foreground">
150	            {config.company_name}
151	          </h1>
152	          {config.tagline && (
153	            <p className="text-lg text-muted-foreground">{config.tagline}</p>
154	          )}
155	          {config.about && (
156	            <p className="text-sm text-muted-foreground max-w-2xl mx-auto leading-relaxed mt-2">
157	              {config.about}
158	            </p>
159	          )}
160	          <Badge
161	            variant="secondary"
162	            className="mt-4 text-sm"
163	            style={{ borderColor: brandColor + "40" }}
164	          >
165	            {jobs.length} Open Position{jobs.length !== 1 ? "s" : ""}
166	          </Badge>
167	        </div>
168	      </div>
169	
170	      {/* Department filter */}
171	      {departments.length > 1 && (
172	        <div className="max-w-4xl mx-auto px-4 pt-6 flex gap-2 flex-wrap">
173	          <button
174	            onClick={() => setSelectedDept(null)}
175	            className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
176	              !selectedDept
177	                ? "text-white"
178	                : "bg-muted text-muted-foreground hover:bg-muted/80"
179	            }`}
180	            style={!selectedDept ? { backgroundColor: brandColor } : undefined}
181	          >
182	            All ({jobs.length})
183	          </button>
184	          {departments.map((dept) => (
185	            <button
186	              key={dept}
187	              onClick={() => setSelectedDept(dept)}
188	              className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
189	                selectedDept === dept
190	                  ? "text-white"
191	                  : "bg-muted text-muted-foreground hover:bg-muted/80"
192	              }`}
193	              style={
194	                selectedDept === dept
195	                  ? { backgroundColor: brandColor }
196	                  : undefined
197	              }
198	            >
199	              {dept} ({jobs.filter((j) => j.department === dept).length})
200	            </button>
201	          ))}
202	        </div>
203	      )}
204	
205	      {/* Job listings */}
206	      <main className="flex-1 max-w-4xl mx-auto px-4 py-6 w-full">
207	        {filteredJobs.length === 0 ? (
208	          <div className="text-center py-16 space-y-3">
209	            <div className="w-14 h-14 rounded-full bg-muted flex items-center justify-center mx-auto">
210	              <Briefcase className="h-7 w-7 text-muted-foreground/40" />
211	            </div>
212	            <h2 className="text-base font-medium text-foreground">
213	              No open positions right now
214	            </h2>
215	            <p className="text-sm text-muted-foreground">
216	              Check back soon for new opportunities.
217	            </p>
218	          </div>
219	        ) : (
220	          <div className="grid gap-4">
221	            {filteredJobs.map((job) => (
222	              <JobListingCard
223	                key={job.id}
224	                id={job.id}
225	                title={job.title}
226	                location={job.location}
227	                department={job.department}
228	                employmentType={job.employment_type}
229	                salaryRange={job.salary_range}
230	                createdAt={job.created_at}
231	                brandColor={brandColor}
232	                onApply={handleApply}
233	              />
234	            ))}
235	          </div>
236	        )}
237	      </main>
238	
239	      {/* Footer */}
240	      <footer className="py-6 text-center border-t border-border">
241	        <p className="text-xs text-muted-foreground">
242	          Powered by{" "}
243	          <Link
244	            to="/"
245	            className="text-primary font-medium hover:text-primary/80 transition-colors"
246	          >
247	            Rankora
248	          </Link>
249	        </p>
250	      </footer>
251	    </div>
252	  );
253	}
254	
