input.new_string:
if (configId) {
  const { error } = await (supabase as any)
    .from("career_page_config")
    .update(payload)
    .eq("id", configId);
  if (error) throw error;
} else {
  const { data: inserted, error } = await (supabase as any)
    .from("career_page_config")
    .insert(payload)
    .select("id")
    .single();
  if (error) throw error;
  // Capture the new row id so subsequent saves use UPDATE, not INSERT.
  // Without this, a second save attempt would hit the UNIQUE(team_id) constraint.
  if (inserted?.id) {
    setConfigId(inserted.id as string);
  }
}
